-- The update reminder e-mail with the logo's new colours (available, markets, gold: option B1, chosen by
-- Nicolas on 12 November 2026). Only the HTML of the e-mail changes: the same function, replaced; its rights
-- revoked again as in 20261111130000_send_reminders.sql. No table, no data touched.
-- Generated by: python3 -I scripts/emails/gen_emails.py --reminder-sql (do not edit by hand).
-- The reminder e-mail's HTML, with the account's unsubscribe link in place of {{UNSUBSCRIBE}}.
create or replace function public.reminder_email_html(unsubscribe_url text) returns text
language sql
immutable
set search_path = ''
as $fn$
  select replace($email$<!doctype html>
<html lang="fr">
